function frameFruit(detail=false){if(!botanical||cfg.view!=='fruit')return;if(detail&&botanical.inspectFocus){treeTarget=botanical.inspectFocus;distance=botanical.inspectDistance||.038;angle=(SPECIES[cfg.type].compound==='bipinnate'||cfg.type==='maple'||cfg.type==='redbud')?Math.PI/2:0;elevation=.02;}else{treeTarget=botanical.bounds.min.map((v,i)=>(v+botanical.bounds.max[i])*.5);distance=fitDistance;angle=(SPECIES[cfg.type].compound==='bipinnate'||cfg.type==='maple'||cfg.type==='redbud')?1.4:.35;elevation=.08;}treeCenter=treeTarget[1];}
function studyCamera(){if(['leaf','surface'].includes(cfg.view)){angle=1.5;elevation=.07;}else if(cfg.view==='shoot'){angle=.7;elevation=.13;}else if(cfg.view==='bark'){angle=0;elevation=.02;}else if(cfg.view==='wood'){angle=.45;elevation=.13;}else if(cfg.view==='roots'){angle=.55;elevation=.65;}else if(cfg.view==='flower'){angle=['dawnredwood','chinesepine'].includes(cfg.type)?1.15:cfg.type==='sakura'?(cfg.flowerStage==='bud'?.65:0):cfg.type==='ginkgo'?0:.45;elevation=cfg.type==='sakura'?.07:.14;}else if(cfg.view==='fruit'){angle=(SPECIES[cfg.type].compound==='bipinnate'||cfg.type==='maple'||cfg.type==='redbud')?1.4:.35;elevation=.08;}}
function frameFlower(part='bloom'){if(cfg.view!=='flower'||!botanical?.stats.flowerStudy)return;const f=botanical.stats.flowerStudy;if(part==='center'){treeTarget=f.focus;distance=f.inspectDistance;}else if(part==='surface'){treeTarget=f.surfaceFocus;distance=f.surfaceDistance;}else{treeTarget=cfg.flowerLayout==='cluster'?botanical.bounds.min.map((v,i)=>(v+botanical.bounds.max[i])*.5):f.center;distance=fitDistance;}treeCenter=treeTarget[1];studyCamera();}
function switchStudy(view){cfg.view=view;if(view==='bark')cfg.lightAngle=65;if(view==='shoot'&&cfg.shootStage==='extending'&&['autumn','winter'].includes(cfg.season))cfg.season='summer';sync();studyCamera();updateBotany();schedule()}
function setupBotany(){studyCamera();
 $$('button[data-view]').forEach(b=>b.onclick=()=>switchStudy(b.dataset.view));
 $('#inspect-flower').onclick=()=>switchStudy('flower');$('#flower-frame').onclick=()=>frameFlower('bloom');$('#flower-center').onclick=()=>frameFlower('center');$('#flower-surface').onclick=()=>frameFlower('surface');for(const key of ['flowerLayout','flowerStage','flowerSex'])$('#'+key).onchange=e=>{cfg[key]=e.target.value;studyCamera();schedule();};
 $('#inspect-fruit').onclick=()=>switchStudy('fruit');$('#fruit-frame').onclick=()=>frameFruit(false);$('#fruit-detail').onclick=()=>frameFruit(true);$('#fruit-stage').onchange=e=>{cfg.fruitStage=e.target.value;sync();updateBotany();schedule()};
 $('#inspect-roots').onclick=()=>switchStudy('roots');$('#fine-roots').onchange=e=>{cfg.fineRoots=e.target.checked;schedule()};$('#inspect-wood').onclick=()=>switchStudy('wood');$('#inspect-bark').onclick=()=>switchStudy('bark');$('#bark-raking').onclick=()=>{cfg.lightAngle=78;sync();};$('#bark-front').onclick=()=>{cfg.lightAngle=0;sync();};$('#bark-frame').onclick=()=>{studyCamera();treeTarget=botanical.inspectFocus??treeTarget;distance=fitDistance;};$('#wood-part').onchange=e=>{cfg.woodPart=e.target.value;schedule()};
 $('#shoot-stage').onchange=e=>{cfg.shootStage=e.target.value;if(cfg.shootStage==='extending'&&['autumn','winter'].includes(cfg.season))cfg.season='summer';sync();schedule()};$('#leaf-upper').onclick=()=>{if(['pine','chinesepine'].includes(cfg.type)){cfg.needleFace='convex';return switchStudy('surface');}studyCamera();distance=fitDistance;};$('#leaf-lower').onclick=()=>{if(['pine','chinesepine'].includes(cfg.type)){cfg.needleFace='flat';return switchStudy('surface');}studyCamera();angle-=Math.PI;distance=fitDistance;};$('#reproductive').onchange=e=>{cfg.reproductive=e.target.checked;schedule()};
 $('#botany-details').onclick=()=>$('#botany-modal').showModal();$('.bot-close').onclick=()=>$('#botany-modal').close();updateBotany();
}
