 if(botanical&&botanical.view===cfg.view){let bounds=cfg.view==='tree'?botanical.aboveGroundBounds:botanical.bounds;let size=bounds.max.map((v,i)=>v-bounds.min[i]),unit=['tree','wood','roots'].includes(cfg.view)?' m':' mm',scale=['tree','wood','roots'].includes(cfg.view)?1:1000;$('#dimensions').textContent=(size[1]*scale).toFixed(['tree','wood','roots'].includes(cfg.view)?1:0)+unit+' tall · '+(Math.max(size[0],size[2])*scale).toFixed(['tree','wood','roots'].includes(cfg.view)?1:0)+unit+' wide · '+botanical.stats.buds+' buds';$('#tree-name').textContent=cfg.view==='flower'?floral.name:cfg.view==='tree'?sp.name:cfg.view==='shoot'?sp.name+' · shoot':sp.name+(cfg.view==='flower'?' · '+floral.name:cfg.view==='fruit'?' · '+FRUIT_NOTES[cfg.type].name:cfg.view==='roots'?' · root system':cfg.view==='wood'?' · wood':cfg.view==='bark'?' · bark':cfg.view==='surface'?' · leaf surface':(cfg.type==='pine'||cfg.type==='chinesepine')?' · needle pair':' · leaf');$('#tree-latin').textContent=sp.latin+' · '+(cfg.view==='flower'?'Reproductive study · Seed '+cfg.seed:cfg.view==='fruit'?cfg.fruitStage+' study · Seed '+cfg.seed:cfg.view==='roots'?'Exposed structural and feeder roots · Seed '+cfg.seed:cfg.view==='wood'||cfg.view==='bark'?'Representative '+cfg.woodPart+' · Seed '+cfg.seed:cfg.view==='tree'?'Seed '+cfg.seed:(cfg.view==='shoot'?'Mature target ':'Blade / needle ')+Math.round(cfg.leafSize*1000)+' mm · Seed '+cfg.seed)}
